package org.apache.commons.jxpath.ri.compiler;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.Arrays;
import java.util.Collection;
import java.util.Collections;
import java.util.HashSet;
import java.util.Iterator;
import org.apache.commons.jxpath.Expression;
import org.apache.commons.jxpath.Pointer;
import org.apache.commons.jxpath.ri.EvalContext;
import org.apache.commons.jxpath.ri.InfoSetUtil;
import org.apache.commons.jxpath.ri.axes.InitialContext;
import org.apache.commons.jxpath.ri.axes.SelfContext;
import org.apache.commons.jxpath.ri.context.EvalContext;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.spy;
import static org.mockito.Mockito.when;

public class CoreOperationCompare_findMatch_TriageGen2Test {

    private CoreOperationCompare coreOperationCompare;
    private Expression mockExpr1;
    private Expression mockExpr2;

    @Before
    public void setUp() {
        mockExpr1 = Mockito.mock(Expression.class);
        mockExpr2 = Mockito.mock(Expression.class);
        // We use spy because findMatch is protected and calls contains() which is also protected
        coreOperationCompare = spy(new CoreOperationCompare(mockExpr1, mockExpr2));
    }

    @Test
    public void testFindMatch_EmptyIterators() {
        Iterator<String> lit = Collections.emptyIterator();
        Iterator<String> rit = Collections.emptyIterator();

        boolean result = coreOperationCompare.findMatch(lit, rit);

        assertFalse("Should return false when both iterators are empty", result);
    }

    @Test
    public void testFindMatch_LeftEmptyRightHasElements() {
        Iterator<String> lit = Collections.emptyIterator();
        Iterator<String> rit = Arrays.asList("A", "B").iterator();

        // Since left is empty, contains should always return false
        when(coreOperationCompare.contains(any(Iterator.class), eq("A"))).thenReturn(false);
        when(coreOperationCompare.contains(any(Iterator.class), eq("B"))).thenReturn(false);

        boolean result = coreOperationCompare.findMatch(lit, rit);

        assertFalse("Should return false when left iterator is empty", result);
    }

    @Test
    public void testFindMatch_RightEmptyLeftHasElements() {
        Iterator<String> lit = Arrays.asList("A", "B").iterator();
        Iterator<String> rit = Collections.emptyIterator();

        boolean result = coreOperationCompare.findMatch(lit, rit);

        assertFalse("Should return false when right iterator is empty", result);
    }

    @Test
    public void testFindMatch_MatchFound() {
        Iterator<String> lit = Arrays.asList("A", "B").iterator();
        Iterator<String> rit = Arrays.asList("C", "B", "D").iterator();

        // Mock contains to return true when it finds "B"
        // Note: The implementation passes a new iterator of the HashSet to contains
        when(coreOperationCompare.contains(any(Iterator.class), eq("C"))).thenReturn(false);
        when(coreOperationCompare.contains(any(Iterator.class), eq("B"))).thenReturn(true);

        boolean result = coreOperationCompare.findMatch(lit, rit);

        assertTrue("Should return true when a match is found", result);
    }

    @Test
    public void testFindMatch_NoMatchFound() {
        Iterator<String> lit = Arrays.asList("A", "B").iterator();
        Iterator<String> rit = Arrays.asList("C", "D").iterator();

        when(coreOperationCompare.contains(any(Iterator.class), eq("C"))).thenReturn(false);
        when(coreOperationCompare.contains(any(Iterator.class), eq("D"))).thenReturn(false);

        boolean result = coreOperationCompare.findMatch(lit, rit);

        assertFalse("Should return false when no match is found", result);
    }
}
